    private WireMockServer provider;
    private HttpPaymentGateway gateway;

    @BeforeEach
    void startProvider() {
        provider = new WireMockServer(WireMockConfiguration.options().dynamicPort());
        provider.start();
        gateway = new HttpPaymentGateway(RestClient.builder().baseUrl(provider.baseUrl()).build());
    }

    @AfterEach
    void stopProvider() {
        provider.stop();
    }

    private void providerAnswers(int status, String body) {
        provider.stubFor(post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(status)
                        .withHeader("Content-Type", "application/json").withBody(body)));
    }

    @Test
    void the_authorization_request_is_sent_as_json_to_the_provider() {
        providerAnswers(200, "{\"status\":\"approved\"}");

        gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));

        provider.verify(1, postRequestedFor(urlEqualTo("/v1/authorizations"))
                .withHeader("Content-Type", com.github.tomakehurst.wiremock.client.WireMock.containing("application/json"))
                .withRequestBody(equalToJson("{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}", false, false)));
    }

    @Test
    void an_approved_answer_is_read_as_approved() {
        providerAnswers(200, "{\"status\":\"approved\"}");

        assertThat(gateway.authorize("ORD-1", new Money(BigDecimal.TEN, "EUR")))
                .isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_read_as_declined() {
        providerAnswers(200, "{\"status\":\"declined\"}");

        assertThat(gateway.authorize("ORD-2", new Money(BigDecimal.TEN, "EUR")))
                .isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void additional_fields_in_the_answer_are_tolerated() {
        providerAnswers(200, "{\"status\":\"approved\",\"id\":\"auth-9\",\"extra\":{\"a\":1}}");

        assertThat(gateway.authorize("ORD-3", new Money(BigDecimal.TEN, "EUR")))
                .isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_refusal_with_402_is_read_as_declined() {
        providerAnswers(402, "{\"error\":\"payment_required\"}");

        assertThat(gateway.authorize("ORD-4", new Money(BigDecimal.TEN, "EUR")))
                .isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_rejected_request_is_reported_as_a_failure_not_a_decline() {
        providerAnswers(400, "{\"error\":\"invalid_request\"}");

        assertThatThrownBy(() -> gateway.authorize("ORD-5", new Money(BigDecimal.TEN, "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_outage_is_reported_as_a_failure_not_a_decline() {
        providerAnswers(503, "");

        assertThatThrownBy(() -> gateway.authorize("ORD-6", new Money(BigDecimal.TEN, "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("503");
    }

    @Test
    void an_unknown_status_is_never_treated_as_approved() {
        providerAnswers(200, "{\"status\":\"pending\"}");

        assertThat(gateway.authorize("ORD-8", new Money(BigDecimal.TEN, "EUR")))
                .isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_answer_without_status_is_never_treated_as_approved() {
        providerAnswers(200, "{}");

        assertThat(gateway.authorize("ORD-9", new Money(BigDecimal.TEN, "EUR")))
                .isEqualTo(AuthorizationOutcome.DECLINED);
    }
}
